import{_ as o,C as r,o as i,c as n,j as a,a as l,E as d,a6 as t}from"./chunks/framework.DIp0zHSV.js";const c="/dev/releases/2026.10.0/showcase-social.webm",h="/dev/releases/2026.10.0/yaml-editor.webp",u="/dev/releases/2026.10.0/chart.webp",g="/dev/releases/2026.10.0/chart-studio.webp",p="/dev/releases/2026.10.0/data-grid.webp",m="/dev/releases/2026.10.0/rule-apply.webp",f="/dev/releases/2026.10.0/processor-preview.webp",w="/dev/releases/2026.10.0/template-sandbox.webp",b="/dev/releases/2026.10.0/provenance.webp",y="/dev/releases/2026.10.0/showcase.webm",v="/dev/releases/2026.10.0/dashboard-gallery.webp",k="/dev/releases/2026.10.0/health-check.webp",_="/dev/releases/2026.10.0/slider-drag-badge.webm",P=JSON.parse('{"title":"LCARdS 2026.10.0","description":"Easier to start, nicer to live with: rebuilt docs with live cards and a dashboard gallery, AI help, faster dashboards, consistent colours, rebuilt charts and data grids. Needs Home Assistant 2026.10.","frontmatter":{"version":"2026.10.0","status":"testing","summary":"Easier to start, nicer to live with: rebuilt docs with live cards and a dashboard gallery, AI help, faster dashboards, consistent colours, rebuilt charts and data grids. Needs Home Assistant 2026.10.","breaking":true,"notes_through":"1c59b5bcd926"},"headers":[],"relativePath":"releases/2026.10.0.md","filePath":"releases/2026.10.0.md","lastUpdated":1792205873000}'),A={name:"releases/2026.10.0.md"};function S(x,e,C,L,T,q){const s=r("ReleaseMeta");return i(),n("div",null,[e[0]||(e[0]=a("h1",{id:"lcards-2026-10-0",tabindex:"-1"},[l("LCARdS 2026.10.0 "),a("a",{class:"header-anchor",href:"#lcards-2026-10-0","aria-label":'Permalink to "LCARdS 2026.10.0"'},"​")],-1)),d(s),e[1]||(e[1]=a("p",null,[a("video",{class:"release-shot",src:c,title:"An empty LCARS view builds itself stage by stage: elbows slide in, sidebar buttons follow, a ship display draws its shield arcs and lines, then a chart, a room table and Picard gauges appear; lights switch on and a red alert plays",autoplay:"",loop:"",muted:"",playsinline:""})],-1)),e[2]||(e[2]=t('<p>A big release focused on making LCARdS more approachable and easier to start with, and an overall increase in usability and reliability.</p><p>New to LCARdS? The overhauled docs walk you from install to your first screen. Examples throughout the docs now mount <em>real live cards</em> to demonstrate the config. You can even use the card playgrounds to try out different options before using them in your dashboard.</p><p>Already running it? Your dashboards will load much faster - lazy loading components when needed. Colours and alert modes behave the same in every card, charts and data grids are completely overhauled (see below), the studios share one polished look, if when something does go wrong, a health check tells you what and how to fix it.</p><p>Speaking of dashboards, there is a small gallery of dashboards that demo LCARdS functionality and includes the config to copy. The new <em>LCARdS skill</em> enables an AI assistant to fully underdstand LCARdS - it can write accurate working configs, and even review existing configs and fix it for you.</p><h2 id="before-you-update" tabindex="-1">Before you update <a class="header-anchor" href="#before-you-update" aria-label="Permalink to &quot;Before you update&quot;">​</a></h2><ul><li><strong>Home Assistant 2026.10 or newer is required.</strong> HA Marketplace (formerly HACS) will not offer the upgrade on HA versions below 2026.10.</li><li><strong>Charts and Data Grids use a new config format.</strong> Your existing cards <em>will keep working</em>: they are converted on the fly at runtime until you update the config. To update, just open each one in the card editor and press Save to store the new form. See the <a href="/dev/cards/chart/upgrading.html">chart</a> and <a href="/dev/cards/data-grid/upgrading.html">data grid</a> upgrade pages.</li><li><strong>Rule priority on cards is fixed.</strong> The higher <code>priority</code> wins, as the <a href="/dev/core/rules/#priority">rules docs</a> always said. If you set priorities on a card&#39;s rules, check that the right one still applies.</li></ul><h2 id="new-features" tabindex="-1">New features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New features&quot;">​</a></h2><h3 id="documentation-tng" tabindex="-1">Documentation:TNG <a class="header-anchor" href="#documentation-tng" aria-label="Permalink to &quot;Documentation:TNG&quot;">​</a></h3><p>The docs site is rebuilt from the ground up for beginners and for exploring:</p><ul><li><strong>Start here:</strong> one path from <a href="/dev/getting-started/installation.html">installing LCARdS</a> to <a href="/dev/getting-started/building-dashboards.html">building your first dashboard</a>, with a <a href="/dev/getting-started/getting-help.html">Getting help</a> checklist when something goes wrong.</li><li><strong>How LCARdS works:</strong> an interactive diagram on <a href="/dev/getting-started/what-is-lcards.html">What is LCARdS</a> designed to help explore and understand how the parts of LCARdS work together with HA. Click any part to see what it works with, or play a scenario (alert mode, rules, data sources and more) to see a step by step walkthrough.</li><li><strong>Live cards everywhere:</strong> over a hundred examples render the real cards, and card pages show galleries of every preset and style.</li><li><strong>Playgrounds:</strong> edit a button, elbow, slider, select menu, chart or data grid with completion and a live preview, then copy the YAML. Animation presets, filters, background effects and data source processors can be tried right on their reference pages.</li><li><strong>A <a href="/dev/getting-started/dashboard-gallery.html">dashboard gallery</a>:</strong> seven complete dashboards to copy, each recorded in action.</li><li><strong><a href="/dev/getting-started/config-checker.html">Check Your Config</a>:</strong> paste a card or a whole dashboard and get plain-language problems, line by line, with links to the right page.</li><li><strong>Docs for your version:</strong> the stable release, the development docs and every past release, with a switcher by the title. Each editor tab links straight to its page.</li></ul><h3 id="help-from-ai-and-help-built-in" tabindex="-1">Help from AI, and help built in <a class="header-anchor" href="#help-from-ai-and-help-built-in" aria-label="Permalink to &quot;Help from AI, and help built in&quot;">​</a></h3><p>LCARdS now comes ready for AI assistants, so Claude, ChatGPT and others can write cards and even whole dashboards that actually work:</p><ul><li><strong>The LCARdS skill for Claude:</strong> a plugin for Claude Code (install it with two <code>/plugin</code> commands and it keeps itself up to date) and a download for claude.ai and the Claude apps; see <a href="/dev/getting-started/ai-assistance.html">Getting AI Help</a>. It teaches Claude every option, built-in preset and colour for your version, asks for your real entity ids instead of inventing them, and checks its YAML before handing it over. It follows the <strong>Open Agent Skills</strong> standard.</li><li><strong>Fix existing YAML:</strong> paste a config into Claude with the skill and ask it to check and fix it.</li><li><strong>Your home&#39;s context:</strong> with the community <a href="https://github.com/homeassistant-ai/ha-mcp" target="_blank" rel="noreferrer">ha-mcp</a> server, Claude can look up your areas and entities itself.</li><li><strong>Other assistants:</strong> for assistants that cannot use the skill, a validated schema for every card is provided for you to attach to the chat, and an <code>llms.txt</code>/<code>llms-full.txt</code> for tools that look for one.</li><li><strong>The same checker everywhere:</strong> in the skill, <a href="/dev/getting-started/config-checker.html">in your browser</a> and on the command line; it finds unknown keys and misspelt names and suggests the right one.</li></ul><p>See <a href="/dev/getting-started/ai-assistance.html">Getting AI help</a>.</p><details class="details custom-block"><summary>Prefer to write YAML yourself? The LCARdS YAML tab in every card editor now knows the card&#39;s schema</summary><ul><li><strong>Completion</strong> for keys at the cursor (nested ones and list items included), their values and your entity ids.</li><li><strong>Hover help</strong> on any key: what it does, its type, default and allowed values.</li><li><strong>Options here:</strong> a panel listing everything that can go at the cursor, with Insert and a link to its docs.</li><li><strong>Mistakes underlined as you type:</strong> YAML errors, unknown keys and wrong values, plus a one-click fix for colours like <code>#ff9900</code> that YAML would otherwise read as a comment.</li></ul><p>The same help works in the docs playgrounds and the studios&#39; YAML tabs.</p><img class="release-shot" alt="The button editor&#39;s YAML tab: completion suggesting animations as a key is typed, and the Options here panel listing the keys that fit, each with Insert and Docs" src="'+h+'"></details><h3 id="charts-rebuilt" tabindex="-1">Charts, rebuilt <a class="header-anchor" href="#charts-rebuilt" aria-label="Permalink to &quot;Charts, rebuilt&quot;">​</a></h3><p>Charts has been rebuilt to be more intutitive. History, long-term statistics and LCARdS data sources in one <code>sources:</code> list, with time spans and grouping like apexcharts-card, several y axes, no point cap and upgraded to ApexCharts 7 library.</p><p>See <a href="/dev/cards/chart/series.html">Series and time</a> or try the <a href="/dev/cards/chart/playground.html">chart playground</a>; coming from apexcharts-card, see the <a href="/dev/cards/chart/upgrading.html#coming-from-apexcharts-card">upgrade page</a>.</p><img class="release-shot" alt="An area chart of two temperature sensors over 24 hours" src="'+u+'"><details class="details custom-block"><summary>More on charts</summary><ul><li><code>graph_span</code>, span start, end and offset, and <code>group_by</code> (average, min, max, sum, median, delta and more, plus min/max bands, box plots and candlesticks).</li><li>Per-series units, precision, colours, line style and chart type.</li><li>Pie, donut, gauge, radar and treemap charts plot each series&#39; latest value.</li><li>Chart Studio: a Time and axes section, a YAML tab with completion, and data source management.</li></ul><img class="release-shot" alt="Chart Studio with the series editor and a live preview" src="'+g+'"></details><h3 id="data-grid-rebuilt" tabindex="-1">Data grid, rebuilt <a class="header-anchor" href="#data-grid-rebuilt" aria-label="Permalink to &quot;Data grid, rebuilt&quot;">​</a></h3><p>Conditional cell colours, header rows, tap actions on cells, column formats and <code>highlight_changes</code>, which flashes cells when their value changes. See <a href="/dev/cards/data-grid/data.html">Data</a>, <a href="/dev/cards/data-grid/styling.html">Styling</a> or the <a href="/dev/cards/data-grid/playground.html">data grid playground</a>.</p><img class="release-shot" alt="A data grid with a header row and cells coloured by state" src="'+p+'"><h3 id="main-engineering-and-the-studios" tabindex="-1">Main Engineering and the Studios <a class="header-anchor" href="#main-engineering-and-the-studios" aria-label="Permalink to &quot;Main Engineering and the Studios&quot;">​</a></h3><p>Every studio and Main Engineering panel now shares one style: tabs, a live preview, short help and the same buttons. New inside: updated rules editor you edit in context, a live processor preview for data sources, revamped template sandbox, an updated provenance inspector that shows where any value comes from, and the theme tokens each card uses. See <a href="/dev/cards/main-engineering.html">Main Engineering</a>.</p><details class="details custom-block"><summary>Pictures and details</summary><ul><li><strong>Rules, edited in context:</strong> a rule&#39;s Apply section is YAML that knows your dashboard. Completion offers every card id on the page, and the patch for a card completes against that card&#39;s own options (style, text, icons, animations and the rest), with hover help and the Options here panel. &quot;Start with this card&quot; fills in the card you are editing, a table lists the ids, types and tags you can target, and new rules show in the list straight away. See <a href="/dev/core/rules/">Rules</a>.</li></ul><img class="release-shot" alt="Editing a rule&#39;s Apply section: in the patch for the warp_core button, completion lists the button&#39;s own options, the Options here panel shows overlays, warp_core, and the targets on this page are listed below" src="'+m+'"><ul><li><strong>Data sources:</strong> processors edited inline in the order they run, previewed against the raw values. Once you are happy, &quot;Use in a chart&quot; gives you a fully working <code>lcards-chart</code> config.</li></ul><img class="release-shot" alt="Data source dialog: two smoothing processors previewed against the raw history" src="'+f+'"><ul><li><strong>Templates:</strong> each templated field shows its live result; the sandbox has completion for entities, attributes, data sources and theme tokens, test values and &quot;Save to field&quot;.</li></ul><img class="release-shot" alt="Template sandbox with a Jinja2 template, its result and the entities it used" src="'+w+'"><ul><li><strong>Provenance:</strong> pick a field to see your config, presets, theme tokens, templates and rules that shaped it, live.</li></ul><img class="release-shot" alt="Provenance inspector tracing a background colour to a theme token" src="'+b+'"><ul><li><strong>Theme:</strong> the tokens a card uses, with their values.</li></ul></details><h3 id="entrance-animations-on-show" tabindex="-1">Entrance animations: <code>on_show</code> <a class="header-anchor" href="#entrance-animations-on-show" aria-label="Permalink to &quot;Entrance animations: `on_show`&quot;">​</a></h3><p>A new animation trigger that plays each time a card appears: when its view opens, when you come back to it, and when a visibility condition shows it. Stagger a few with delays and a view builds itself up; MSD lines and shapes can draw themselves in. See <a href="/dev/core/animations.html#entrance-animations-with-on-show">Entrance animations</a>.</p>',28)),e[3]||(e[3]=a("p",null,[a("video",{class:"release-shot",src:y,title:"An empty LCARS view builds itself stage by stage: elbows slide in, sidebar buttons follow, a ship display draws its shield arcs and lines, then a chart, a room table and Picard gauges appear; lights switch on and a red alert plays",autoplay:"",loop:"",muted:"",playsinline:""})],-1)),e[4]||(e[4]=t('<h3 id="dashboard-gallery" tabindex="-1">Dashboard gallery <a class="header-anchor" href="#dashboard-gallery" aria-label="Permalink to &quot;Dashboard gallery&quot;">​</a></h3><p>From a bridge to a ship&#39;s engineering display: copy the YAML, swap in your entities. See the <a href="/dev/getting-started/dashboard-gallery.html">Dashboard Gallery</a>.</p><img class="release-shot" alt="The Engineering dashboard from the gallery: a ship blueprint in shield arcs with control buttons joined by lines, square sidebar buttons, a systems table and Picard sliders" src="'+v+'"><h3 id="support-and-system-info" tabindex="-1">Support and system info <a class="header-anchor" href="#support-and-system-info" aria-label="Permalink to &quot;Support and system info&quot;">​</a></h3><p>The config panel&#39;s Welcome tab has a new health check section that will quickly check and alert you to possible problems. It validates versions, card-mod or UIX, leftover resources, the HA-LCARS theme, <code>custom:layout-card</code>), each with a fix, and <strong>Report an issue</strong> opens GitHub&#39;s bug form filled in with your system info. See <a href="/dev/getting-started/getting-help.html">Getting help</a>.</p><img class="release-shot" alt="The Support and system info health check" src="'+k+'"><h3 id="slider-drag-value-badge" tabindex="-1">Slider: drag value badge <a class="header-anchor" href="#slider-drag-value-badge" aria-label="Permalink to &quot;Slider: drag value badge&quot;">​</a></h3><p>A badge follows your finger with the value a drag will set, like Home Assistant&#39;s own sliders. See <a href="/dev/cards/slider-card/#drag-value-badge">Drag value badge</a>.</p>',8)),e[5]||(e[5]=a("p",null,[a("video",{class:"release-shot",src:_,title:"A slider showing its value badge while dragged",autoplay:"",loop:"",muted:"",playsinline:""})],-1)),e[6]||(e[6]=t('<h2 id="improvements-fixes" tabindex="-1">Improvements &amp; Fixes <a class="header-anchor" href="#improvements-fixes" aria-label="Permalink to &quot;Improvements &amp; Fixes&quot;">​</a></h2><details class="details custom-block"><summary>...a lot of them</summary><p><strong>Improvements</strong></p><ul><li><strong>Colours, one set of rules:</strong> every colour field accepts the same formats (hex, names, <code>rgb()</code>, <code>hsl()</code>, <code>oklch()</code>, <code>color-mix()</code>, variables, theme tokens and nestable colour functions) See <a href="/dev/core/colours.html#colour-value-formats">Colours</a>.</li><li><strong>Faster dashboards:</strong> by dynanically loading chunks, only when needed, LCARdS main modules is now about 420 KB instead of 9 MB; editors and the config panel load when you open them.</li><li><code>base()</code> colour modifier works in animation and effect settings.</li><li>Entity pickers and other HA controls inside LCARdS dialogs work again (HA 2026.10+)</li><li>Cards in alert, connection or portal overlays stay live on pages without LCARdS cards.</li><li>Layout view rows collapse for every kind of visibility condition, without recalculating on each state change.</li><li>Data sources load full-resolution history first and wait for Home Assistant on a cold start.</li><li>Editors: more concise messages, standardised against Home Assistant&#39;s native dialogs. Config panel: one look, grouped Storage keys, fix live Pack Explorer previews.</li><li>Fewer false validation warnings: <code>calc()</code>/<code>clamp()</code> sizes, <code>0</code> spacing, numeric grid positions, MSD with only a <code>view_box</code>, overlay tags and animations, animations without a <code>trigger</code>, <code>on_double_tap</code>/<code>on_datasource_change</code>, frame elbow and symbiont options.</li><li>HA-LCARS ships the LCARdS theme profiles; the new <a href="/dev/configuration/ha-lcars-theme-lab.html">Theme Lab guide</a> builds your own. New <a href="/dev/cards/layout-card/">Layout Card</a> page and documented <a href="/dev/cards/elbow/#frame-type">frame elbows</a>.</li></ul><p><strong>Fixes</strong></p><ul><li><strong>Button:</strong> colour animations on the background and border now play (<a href="https://github.com/snootched/lcards/issues/401" target="_blank" rel="noreferrer">#401</a>).</li><li><strong>Charts:</strong> several series no longer jump as the later ones load; garbled month names, invisible custom tooltips, ignored gradients, font sizes and annotation colours, long y-axis decimals, hairline statistics columns, and charts stopping after a view change.</li><li><strong>Data grid:</strong> card size errors, double-escaped cells, animations leaking after removal; template and data source cells refresh; the studio edits columns correctly.</li><li><strong>Slider:</strong> card animations only ran with a tap or hold action (never on gauge or pills); % units for lights, covers, fans, humidifiers and valves; units for non-numeric entities; templated labels showed code until the entity changed.</li><li><strong>Elbow:</strong> a single <code>segment.color</code> value was ignored; the editor&#39;s text zones were wrong for frame, open and contained elbows.</li><li><strong>Alert overlay:</strong> with no size set the symbol didn&#39;t show; it now fills 60% of the screen&#39;s width by default.</li><li><strong>Rules:</strong> a plain-text <code>condition:</code> (no <code>[[[ ]]]</code> or <code>{{ }}</code>) matched every state and now never matches, with a warning (<a href="/dev/core/rules/conditions.html">conditions</a>); rules stopped after HA moved a card; <code>entity_attr</code> never matched; JavaScript conditions read the previous state or didn&#39;t react; <code>condition: |</code> blocks broke; <code>apply.profiles</code> (never worked) now warns.</li><li><strong>Templates:</strong> inline <code>{theme:...}</code> tokens rendered empty; mixing <code>{token}</code> and <code>{{ jinja }}</code> lost the Jinja2 part.</li><li><strong>Data sources:</strong> <code>input_source</code> ignored by statistics and smoothing; expressions before their sources; empty <code>attribute: state</code> series; no history for new sources; <code>{ds:temp.smoothed}</code> text never filled in; the snake_case timing keys the editor writes (<code>window_seconds</code>, <code>min_emit_ms</code> and so on) were ignored.</li><li><strong>Colours:</strong> false &quot;Format validation failed&quot; warnings; <code>mix()</code> flagged invalid; nested functions and tokens inside functions; <code>theme:darken(...)</code> never evaluated; transparency lost by <code>darken()</code>, <code>lighten()</code>, <code>saturate()</code>; <code>base()</code> following the alert for some theme colours.</li><li><strong>Select menu:</strong> other cards on the same entity showed <code>on</code>/<code>off</code> instead of the option.</li><li><strong>Layout:</strong> the Layout Studio&#39;s grid tools missing on a fresh page; the layout view&#39;s edit hint covering placed cards.</li><li><strong>Docs examples that never worked:</strong> per-card sounds written as <code>lcards_default:nav_forward</code> (use <code>lcards_default_nav</code>), alert symbol presets <code>red</code>/<code>yellow</code> (use <code>condition_red</code>/<code>condition_yellow</code>), and <code>var(--lcards-alert-red)</code> colours (use <code>var(--lcars-alert-red)</code>).</li><li><strong>Editors:</strong> completion and hover popups in dialogs (the rule editor, the studios) opened away from the cursor.</li><li><strong>Also:</strong> shape texture colour templates and <code>match-light</code>; chart series names with a dot flagged as missing entities; icon buttons without icons; LCARS shell elbows logging warnings.</li></ul></details>',2))])}const D=o(A,[["render",S]]);export{P as __pageData,D as default};
